def check_rectangle(grid):
    H = len(grid)
    W = len(grid[0])

    # Check if there's at least one black cell
    has_black_cell = any('#' in row for row in grid)
    if not has_black_cell:
        return "No"

    # Find the first black cell
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                start_row, start_col = i, j

    # Check if all other black cells are adjacent to the starting black cell
    for i in range(start_row - 1, -1, -1):
        if grid[i][start_col] != '.':
            return "No"
    for i in range(start_row + 1, H):
        if grid[i][start_col] != '.':
            return "No"
    for j in range(start_col - 1, -1, -1):
        if grid[start_row][j] != '.':
            return "No"
    for j in range(start_col + 1, W):
        if grid[start_row][j] != '.':
            return "No"

    return "Yes"

# Read input
H, W = map(int, input().split())
grid = [input() for _ in range(H)]

# Print result
print(check_rectangle(grid))

import sys

def check_rectangle(painted_cells):
    if len(painted_cells) < 4:
        return False
    x_min, y_min = min(painted_cells, key=lambda cell: cell[0])[0], min(painted_cells, key=lambda cell: cell[1])[1]
    x_max, y_max = max(painted_cells, key=lambda cell: cell[0])[0], max(painted_cells, key=lambda cell: cell[1])[1]
    for i in range(x_min, x_max + 1):
        for j in range(y_min, y_max + 1):
            if (i, j) not in painted_cells:
                return False
    return True

def main():
    input_data = sys.stdin.read().split()
    H, W = int(input_data[0]), int(input_data[1])
    grid = [input_data[i] for i in range(2, H + 2)]

    painted_cells = set()
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                painted_cells.add((i, j))

    if check_rectangle(painted_cells):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()

def check_rectangle(grid):
    for i in range(1, len(grid)):
        for j in range(1, len(grid[0])):
            if grid[i][j] == '?' and grid[i-1][j] != '?' and grid[i][j-1] != '?':
                return False
    return True

