def check_rectangle(grid):
    # Check rows for consecutive black cells
    for row in grid:
        for i in range(len(row) - 1):
            if row[i] == '#' and row[i + 1] == '#':
                return False

    # Check columns for consecutive black cells
    for col in zip(*grid):
        for i in range(len(col) - 1):
            if col[i] == '#' and col[i + 1] == '#':
                return False

    return True

H, W = map(int, input().split())
grid = [input() for _ in range(H)]

if check_rectangle(grid):
    print("Yes")
else:
    print("No")
